const label=typeof settings.title==='string'&&settings.title.trim()?settings.title.trim():'我的纪念日';
const raw=typeof settings.date==='string'?settings.date:'';
const valid=/^\d{4}-\d{2}-\d{2}$/.test(raw);
const [year,month,day]=valid?raw.split('-').map(Number):[0,0,0];
const date=new Date(year,month-1,day);
const dayValue=valid&&year>=1&&date.getFullYear()===year&&date.getMonth()===month-1&&date.getDate()===day;
const accent=/^#[0-9a-fA-F]{6}$/.test(settings.accent)?settings.accent:null;
if(accent)root.style.setProperty('--accent',accent);
root.innerHTML='<div class="top"><span class="mark">✦</span><span class="tag">纪念日</span></div><div class="content"><div class="story"><div class="eyebrow">OUR MOMENT · 纪念日</div><strong class="title"></strong><span class="date"></span></div><div class="counter"><span class="number"></span><span class="unit">天</span></div></div><div class="foot"><span class="status"></span><span class="decoration">✦ &nbsp; ✧ &nbsp; ✦</span></div>';
root.querySelector('.title').textContent=label;
const dateText=dayValue?raw.replaceAll('-',' / '):'点击设置日期';
root.querySelector('.date').textContent=dateText;
function draw(){if(!dayValue){root.querySelector('.number').textContent='--';root.querySelector('.status').textContent='等待一个特别的日子';return}
const today=new Date();const utcToday=Date.UTC(today.getFullYear(),today.getMonth(),today.getDate());
const utcEvent=Date.UTC(year,month-1,day);const days=Math.round((utcToday-utcEvent)/86400000);
root.querySelector('.number').textContent=Math.abs(days).toLocaleString('zh-CN');
root.querySelector('.status').textContent=days===0?'就是今天 · 值得纪念':settings.mode==='countdown'?(days>0?'目标日已过去':'距离这一天还有'):(days>0?'我们已经走过':'还未到这一天');
root.querySelector('.unit').textContent='天';}
draw();setInterval(draw,60000);
